import os
import re

from collections import OrderedDict
from xml.etree.ElementTree import ParseError

from taf.sw.security.defensics.clients.http_client import DefensicsHttpClient
from taf.sw.security.defensics.schemas.defensics_v2020_3.test_state import create_test_state_dict
from taf.sw.security.defensics.schemas.defensics_v2020_3.interoperability_probe import (
    create_interoperability_probe_object,
)
from taf.sw.security.defensics.schemas.defensics_v2020_3.last_interoperability_probe import (
    create_last_interoperability_probe_object,
)
from taf.sw.security.defensics.schemas.defensics_v2020_3.rerun_suite import RerunSuiteArgumentsValidator


def save_file(full_path, content):
    dest_dir = os.path.dirname(full_path)
    try:
        os.makedirs(dest_dir)
    except OSError:
        pass  # already exists
    with open(full_path, "wb") as f:
        f.write(content)


class DEFENSICS_v2020_3(object):
    _client = None

    def __init__(self, ip_address, port, token=None, secure=False):
        self._client = DefensicsHttpClient(
            ip_address=ip_address,
            port=port,
            token=token,
            secure=secure,
        )

    def load_suite(self, suite_file, name, use_newest, timeout):
        if use_newest:
            use_newest_flag = "true"
        else:
            use_newest_flag = "false"
        return self._client.send(
            method="POST",
            url="/monitor/load-suite",
            parameters={"file": suite_file, "name": name, "use-newest": use_newest_flag},
            timeout=timeout,
        )

    def get_installed_suites(self, timeout):
        """
        GET request is returning plain text with all installed suites for example:
        "Installed suites:\nsuite.jar\nsuite2.jar\n"
        Method is returning list of suites without 1st line: Installed suites and stripped whitespaces
        """
        installed_suites = self._client.send(
            method="GET", url="/monitor/get-installed-suites", parameters={}, timeout=timeout
        )
        return installed_suites.strip().split("\n")[1:]

    def start_plan(self, run_sequentially, timeout):
        parameters = {} if not run_sequentially else {"test-plan-execution-mode": "sequential"}

        return self._client.send(method="POST", url="/monitor/plan/start", parameters=parameters, timeout=timeout)

    def stop_plan(self, timeout):
        return self._client.send(method="POST", url="/monitor/plan/stop", parameters={}, timeout=timeout)

    def start_suite(self, name, timeout):
        return self._client.send(method="POST", url="/monitor/suite/start", parameters={"suite": name}, timeout=timeout)

    def stop_suite(self, name, timeout):
        return self._client.send(method="POST", url="/monitor/suite/stop", parameters={"suite": name}, timeout=timeout)

    def resume_suite(self, suite, test_run, resume_index_offset, timeout):
        """
        Resuming a stopped run can also be done, parameter given is the suite. Suite must be loaded.
        Suite's most recent test run is resumed.
        """
        parameters = OrderedDict([("suite", suite), ("file", test_run), ("resume-index-offset", resume_index_offset)])

        return self._client.send(method="POST", url="/monitor/resume", parameters=parameters, timeout=timeout)

    def pause_suite(self, name, timeout):
        return self._client.send(method="POST", url="/monitor/suite/pause", parameters={"suite": name}, timeout=timeout)

    def get_suite_status(self, name, timeout):
        parameters = {"suite": name} if name is not None else {}
        status = self._client.send(
            method="GET", url="/monitor/suite/get-status", parameters=parameters, timeout=timeout
        )
        return status.strip()

    def get_testing_status(self, timeout):
        status = self._client.send(
            method="GET", url="/monitor/plan/get-test-state", parameters={}, timeout=timeout
        ).strip()

        if len(status) == 0:
            exc_msg = "Server returned an empty string. Please make sure that there is at least one loaded suite."
            raise RuntimeError(exc_msg)
        else:
            try:
                return create_test_state_dict(status)
            except (ValueError, KeyError):
                exc_msg = "Data returned from server does not match a TestState scheme. Raw data:\n{}"
                exc_msg = exc_msg.format(status)
                raise ValueError(exc_msg)

    def rerun_suite(
        self,
        suite,
        suite_name,
        file_path,
        load_suite,
        setting,
        verdict,
        type_of_rerun,
        instrumentation,
        rerun_preceding,
        timeout,
    ):
        v = RerunSuiteArgumentsValidator(
            suite=suite,
            suite_name=suite_name,
            file_path=file_path,
            load_suite=load_suite,
            setting=setting,
            verdict=verdict,
            type_of_rerun=type_of_rerun,
            instrumentation=instrumentation,
            rerun_preceding=rerun_preceding,
        )

        parameters = OrderedDict(
            [
                ("suite", v.suite),
                ("suite-name", v.suite_name),
                ("file", v.file_path),
                ("load-suite", v.load_suite),
                ("set", v.setting),
                ("verdict", v.verdict),
                ("type", v.type_of_rerun),
                ("instrumentation-method", v.instrumentation),
                ("rerun-preceding", v.rerun_preceding),
            ]
        )

        return self._client.send(method="POST", url="/monitor/suite/rerun", parameters=parameters, timeout=timeout)

    def get_suite_settings(self, name, timeout):
        parameters = {"suite": name} if name is not None else {}
        settings = self._client.send(
            method="GET", url="/monitor/suite/get-setting", parameters=parameters, timeout=timeout
        )
        return settings

    def set_suite_settings(self, name, args, timeout):
        request_body = "\n".join(args)
        return self._client.send(
            method="POST",
            url="/monitor/suite/set-setting-file",
            parameters={"suite": name},
            timeout=timeout,
            data=request_body,
        )

    def get_recent_result_of_plan(self, timeout):
        results_str = self._client.send(
            method="GET", url="/monitor/plan/get-recent-result", parameters={}, timeout=timeout
        )
        return results_str.strip().split("\n")

    def get_recent_result_of_suite(self, timeout):
        results_str = self._client.send(
            method="GET", url="/monitor/suite/get-recent-result", parameters={}, timeout=timeout
        )
        return results_str.strip().split("\n")

    def get_result(self, dest_dir, file_path, name, timeout):
        resp = self._client.send_and_return_response(
            method="GET",
            url="/monitor/get-result",
            parameters=OrderedDict([("suite", name), ("file", file_path)]),
            timeout=timeout,
        )

        output_path = os.path.join(dest_dir, os.path.basename(file_path))
        save_file(output_path, resp.content)

    def get_report(self, dest_dir, result_dir, report_type, timeout):
        supported_types = ("single-html", "zip", "remediation")
        if report_type not in supported_types:
            raise ValueError("`report_type` must be one of: {}".format(", ".join(supported_types)))

        resp = self._client.send_and_return_response(
            method="GET",
            url="/monitor/get-report",
            parameters=OrderedDict([("file", result_dir), ("type", report_type)]),
            timeout=timeout,
        )

        extension = {"application/zip": ".zip", "text/html": ".html"}.get(resp.headers["Content-Type"], "")
        output_path = os.path.join(dest_dir, "report" + extension)
        save_file(output_path, resp.content)

    def start_interoperability_probe(self, name, apply_flag, timeout):
        apply_flag = "true" if str(apply_flag).lower() == "true" else "false"

        data = self._client.send(
            method="POST",
            url="/monitor/suite/interop-probe",
            parameters={"suite": name, "apply": apply_flag},
            timeout=timeout,
        )
        try:
            return create_interoperability_probe_object(data)
        except (ValueError, KeyError):
            exc_msg = "Data returned from server does not match the Interoperability Probe scheme. Raw data:\n{}"
            exc_msg = exc_msg.format(data)
            raise ValueError(exc_msg)
        except ParseError:
            no_value_regex = r"(No value defined for setting)\s\'(.+?)\'\s\((.+?)\)"
            bad_value_regex = r"(Bad value for setting)\s\'(.+?)\'\s\((.+?)\)"
            no_value = re.search(no_value_regex, data)
            bad_value = re.search(bad_value_regex, data)
            if no_value:
                return "\nAn issue was detected in output from interoperability probe:\n{}: {}: {}".format(
                    *no_value.groups()
                )
            elif bad_value:
                return "\nAn issue was detected in output from interoperability probe:\n{}: {}: {}".format(
                    *bad_value.groups()
                )
            else:
                raise

    def get_result_of_previous_interoperability_probe(self, timeout):
        data = self._client.send(
            method="GET", url="/monitor/suite/interop-probe-result", parameters={}, timeout=timeout
        )
        try:
            return create_last_interoperability_probe_object(data)
        except (ValueError, KeyError):
            exc_msg = "Data returned from server does not match the Interoperability Probe scheme. Raw data:\n{}"
            exc_msg = exc_msg.format(data)
            raise ValueError(exc_msg)

    def unload_suite(self, name, timeout):
        return self._client.send(
            method="POST", url="/monitor/suite/unload", parameters={"suite": name}, timeout=timeout
        )

    def kill_server(self, timeout):
        return self._client.send(method="POST", url="/monitor/plan/kill", parameters={}, timeout=timeout)

    def check_all_licenses(self, timeout):
        return self._client.send(method="GET", url="/monitor/suite/check-all-licenses", parameters={}, timeout=timeout)

    def check_license(self, suite, timeout):
        return self._client.send(
            method="GET", url="/monitor/suite/check-license", parameters={"file": suite}, timeout=timeout
        )

    def load_plan(self, plan, timeout):
        return self._client.send(method="POST", url="/monitor/load-plan", parameters={"file": plan}, timeout=timeout)

    def get_plan_status(self, timeout):
        return self._client.send(method="GET", url="/monitor/plan/get-status", parameters={}, timeout=timeout)
